from pathlib import Path
import json
P=Path(__file__).resolve().parents[1]/'data'
def load(n):return json.loads((P/(n+'.json')).read_text())
def save(n,x):(P/(n+'.json')).write_text(json.dumps(x,ensure_ascii=False,indent=2))
def attach(e,rid,url,date,fields,version='браузерная игра, платформа не уточнена',confidence='Прочитана отдельная историческая статья; условия могут зависеть от версии. Независимость от других сайтов не установлена.'):
 e.setdefault('prior_records',[]);e['prior_records']=[x for x in e['prior_records'] if x.get('original_id')!=rid]+[{'original_id':rid,'original_category':'Историческая статья','version':version,'date':date,'fields':fields,'confidence':confidence}]
 if not any(x.get('url')==url for x in e['sources']):e['sources'].append({'url':url,'label':'Прочитанная отдельная статья'})
def make(name,slug,cat,kind):return {'name':name,'slug':slug,'category':cat,'type':kind,'purchase':'нет данных','sale':'нет данных','obtain':'нет данных','use':'нет данных','features':'нет данных','versions':'исторические сведения браузерной игры; см. источник','sources':[],'image':None,'links':[],'event':'нет данных','original_category':kind,'prior_records':[]}
